"""Lane A, batch T3 - blind formula pass writer (Phase 1).
Judgments are authored by the lane classifier below; this script only serialises them.
Reads formula/<id>.json only to copy the fingerprint and verify INCI length.
"""
import json, os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
FORM = os.path.join(ROOT, "formula")
OUT = os.path.join(ROOT, "out", "formula-pass")


def prop(value, conf, rationale, neighbor, counter=None, facts=None, **extra):
    d = {"value": value, "confidence": conf, "rationale": rationale,
         "neighboringAlternative": neighbor}
    if counter:
        d["counterSignal"] = counter
    if facts:
        d["formulaFacts"] = facts
    d.update(extra)
    return d


