def main():
    for bid, d in sorted(P.items()):
        with open(os.path.join(FORM, bid + ".json")) as f:
            pk = json.load(f)
        o = d["other"]
        rec = {
            "blindId": bid,
            "inciFingerprintSha256": pk["inciFingerprintSha256"],
            "phase": "blind_formula_pass",
            "formulaBlock": {"normalization": d["normalization"], "formulaCompleteness": pk["formulaCompleteness"],
                             "formulaSourceTier": pk["formulaSourceTier"], "identityConfidence": pk["identityConfidence"],
                             "rawInciCount": len(pk["canonicalInci"])},
            "directProperties": {
                "cleansingStrength": d["cs"],
                "conditioningLevel": d["cl"],
                "weightPotential": d["wp"],
                "dandruffSupport": o["dandruffSupport"],
                "focusPrimary": o["focusPrimaryProvisional"],
                "focusSecondary": o["focusSecondaryProvisional"],
                "usageRole": o["usageRoleProvisional"],
                "scalpComfortTarget": o["scalpComfortTargetProvisional"],
            },
            "careDirection": o["careDirection"],
            "formulaGateFacts": o["gateFacts"],
            "formulaFacts": [{"ingredient": i, "position": p, "role": r} for i, p, r in d["facts"]],
            "unresolvedMaterialIngredients": d["unresolved"],
        }
        for k in ("cleansingStrength", "conditioningLevel", "weightPotential"):
            assert rec["directProperties"][k]["value"] and rec["directProperties"][k]["rationale"], (bid, k)
        with open(os.path.join(OUT, bid + ".json"), "w") as f:
            json.dump(rec, f, indent=2, ensure_ascii=False)
        print("wrote", bid)


if __name__ == "__main__":
    main()
